def solve(cols,y):
 # equations represented by output bit rows, vars 32
 rows=[]
 for bit in range(32): rows.append([sum(((cols[j]>>bit)&1)<<j for j in range(32)),(y>>bit)&1])
 rank=0
 for j in range(32):
  k=next((k for k in range(rank,32) if rows[k][0]>>j&1),None)
  if k is None:continue
  rows[rank],rows[k]=rows[k],rows[rank]
  for k in range(32):
   if k!=rank and rows[k][0]>>j&1:rows[k][0]^=rows[rank][0];rows[k][1]^=rows[rank][1]
  rank+=1
 x=0
 for mask,v in rows:
  if mask and v:x|=mask&-mask
 return x if rank==32 else None
for s in range(4):
 for drop in range(3):
  datas=[r[0][s:len(r[0])-drop if drop else None] for r in rs]
